        "rightLabel": "Ballerina",
        "rightCode": "import ballerina/constraint;\nimport ballerina/http;\nimport ballerina/io;\n\ntype User record {\n    @constraint:String {\n        minLength: 1,\n        maxLength: 8\n    }\n    string username;\n    @constraint:String {\n        pattern: re `^[\\S]{4,}$`\n    }\n    string password;\n};\n\nservice / on new http:Listener(9090) {\n    resource function post user(User user) returns http:Created {\n        io:println(string `User ${user.username} signed up successfully`);\n        return http:CREATED;\n    }\n}",
